/*
 * A043651  Numbers whose base-12 representation has exactly 2 runs.
 * https://oeis.org/A043651
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 60, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Validated: partial, pass, 60 terms through n = 60 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Numbers whose base‑12 representation has exactly 2 runs.
 * The sequence is generated by scanning the natural numbers in
 * increasing order and selecting only those whose base‑12 digits
 * form two maximal blocks of equal digits. */
/* External linkage */
#include <stdbool.h>

static bool has_two_runs(seq_t x)
{
    seq_t prev = (seq_t)-1;  /* sentinel for “no previous digit” */
    seq_t runs = 0;

    while (x > 0) {
        seq_t d = x % 12;     /* current least‑significant digit */
        x = x / 12;           /* shift right by one base‑12 digit */

        if (d != prev) {      /* a new run starts */
            ++runs;
            prev = d;
            if (runs > 2)     /* early exit if more than two runs */
                return false;
        }
    }
    return runs == 2;
}

seq_t a(idx_t n)
{
    idx_t count = 0;          /* how many qualifying numbers found */
    seq_t x = 12;             /* first term of the sequence */

    while (1) {
        if (has_two_runs(x)) {
            ++count;
            if (count == n)
                return x;
        }
        ++x;                  /* next candidate */
    }
}
